def check_bands(bands):
    bands = sorted(bands)
    if bands[0][0] != 0 or bands[-1][1] != 24:
        raise ValueError("bands must cover 0-24")
    for (_, end, _), (start, _, _) in zip(bands, bands[1:]):
        if start != end:
            raise ValueError(f"gap or overlap at hour {end}")

